import { z } from "zod";
import { MarkDownContent } from "../other.mjs";
import { zRenderFormats } from "../Renderable.mjs";
import { zColor } from "./TxtWidget.mjs";
const zInfo = z.union([z.string(), z.instanceof(MarkDownContent)]);
const zValue = z.object({
    value: z.any(),
    size: z.enum(["xs", "s", "m", "l", "xl"]).default("m"),
    align: z.enum(["start", "end", "center"]).default("start"),
    color: zColor.optional(),
    appearance: z.enum(["card", "well", "inverse"]).optional(),
    // icon: z.string().optional(),
    format: zRenderFormats.optional(),
});
const zCellProps = z.object({
    value: zValue.or(z.array(zValue).min(1)),
    label: z.string().optional(),
    info: zInfo.optional(),
    layout: z.enum(["stack", "row", "grid"]),
    appearance: z.enum(["card", "well", "inverse"]).optional(),
});
export function Cell(define) {
    return define("Txt")
        .props(zCellProps)
        .userEvents({
        click: [z.literal(true), false],
    })
        .render((props) => ({
        label: props.label,
        value: props.value,
        info: props.info,
    }));
}
